using Microsoft.AspNetCore.DataProtection;
using Refahi.Modules.CreditPayments.Domain;
using Refahi.Modules.CreditPayments.Infrastructure;

namespace Refahi.Modules.CreditPayments.Tests;

public sealed class Phase02DomainAndSecurityTests
{
    private static readonly DateTimeOffset Now=new(2026,9,16,10,0,0,TimeSpan.Zero);
    [Fact] public void Merchant_transitions_are_explicit_and_disabled_is_terminal(){var m=MerchantTestFactory.Create(Guid.NewGuid(),"فروشگاه",Now);Assert.Equal(MerchantStatus.Pending,m.Status);m.Activate(Now.AddMinutes(1));m.Suspend(Now.AddMinutes(2));m.Activate(Now.AddMinutes(3));m.Disable(Now.AddMinutes(4));Assert.Throws<CreditPaymentsDomainException>(()=>m.Activate(Now.AddMinutes(5)));}
    [Fact] public void Pending_merchant_cannot_create_terminal(){var m=MerchantTestFactory.Create(Guid.NewGuid(),"فروشگاه",Now);Assert.Throws<CreditPaymentsDomainException>(()=>m.AddTerminal("وب","STORE.Clothing",1,10,["https://merchant.example/callback"],Now));}
    [Theory]
    [InlineData("http://merchant.example/callback")][InlineData("javascript:alert(1)")][InlineData("data:text/plain,x")][InlineData("https://user:pass@merchant.example/callback")][InlineData("https://localhost/callback")][InlineData("https://127.0.0.1/callback")][InlineData("https://[::1]/callback")][InlineData("https://merchant.example/callback#fragment")]
    public void Unsafe_return_urls_are_rejected(string url)=>Assert.Throws<CreditPaymentsDomainException>(()=>SecureUrlPolicy.CanonicalizeReturnUrl(url));
    [Fact] public void Return_url_canonicalization_is_deterministic_and_query_is_part_of_exact_value(){Assert.Equal("https://example.com/callback?a=1",SecureUrlPolicy.CanonicalizeReturnUrl(" HTTPS://EXAMPLE.COM:443/callback?a=1 "));Assert.NotEqual(SecureUrlPolicy.CanonicalizeReturnUrl("https://example.com/callback?a=1"),SecureUrlPolicy.CanonicalizeReturnUrl("https://example.com/callback?a=2"));}
    [Theory][InlineData("https://10.0.0.1/hook")][InlineData("https://192.168.1.1/hook")][InlineData("https://169.254.1.1/hook")]
    public void Webhook_rejects_obvious_private_targets(string url)=>Assert.Throws<CreditPaymentsDomainException>(()=>SecureUrlPolicy.CanonicalizeWebhookUrl(url));
    [Fact] public void Invalid_limits_and_unknown_scopes_are_rejected(){var m=ActiveMerchant();Assert.Throws<CreditPaymentsDomainException>(()=>m.AddTerminal("وب","store",10,1,["https://example.com/c"],Now));var t=m.AddTerminal("وب","STORE.Clothing",1,10,["https://example.com/c"],Now);Assert.Equal("store.clothing",t.ApprovedCategoryCode);Assert.Throws<CreditPaymentsDomainException>(()=>t.AddCredential("id","hash","PBKDF2-SHA256",1,["admin:*"],"bad",null,Now));}
    [Fact] public void Duplicate_urls_after_canonicalization_are_rejected(){var t=ActiveMerchant().AddTerminal("وب","store",1,10,["https://EXAMPLE.com:443/c"],Now);Assert.Throws<CreditPaymentsDomainException>(()=>t.AddReturnUrl("https://example.com/c",Now));}
    [Fact] public void Credential_has_high_entropy_hashes_and_supports_overlap_rotation(){var s=new Pbkdf2CredentialSecretService();var a=s.Generate();var b=s.Generate();Assert.StartsWith("cpg_",a.ClientId);Assert.True(a.Secret.Length>=43);Assert.NotEqual(a.Secret,a.Hash);Assert.True(s.Verify(a.Secret,a.Hash,a.Algorithm,a.Version));Assert.False(s.Verify("wrong",a.Hash,a.Algorithm,a.Version));var t=ActiveMerchant().AddTerminal("وب","store",1,10,["https://example.com/c"],Now);var c1=t.AddCredential(a.ClientId,a.Hash,a.Algorithm,a.Version,[CredentialScopes.PaymentCreate],"old",null,Now);var c2=t.AddCredential(b.ClientId,b.Hash,b.Algorithm,b.Version,[CredentialScopes.PaymentCreate],"new",null,Now);c1.Revoke(Now.AddMinutes(1));Assert.Equal(CredentialStatus.Revoked,c1.Status);Assert.Equal(CredentialStatus.Active,c2.Status);Assert.Throws<CreditPaymentsDomainException>(()=>c1.Revoke(Now.AddMinutes(2)));}
    [Fact] public void Webhook_secret_is_protected_and_rotates_version(){var path=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(path);try{var p=new DataProtectionWebhookSecretProtector(DataProtectionProvider.Create(new DirectoryInfo(path)));var material=p.GenerateAndProtect();Assert.NotEqual(material.Secret,material.Ciphertext);Assert.DoesNotContain(material.Secret,material.Ciphertext);var t=ActiveMerchant().AddTerminal("وب","store",1,10,["https://example.com/c"],Now);var w=t.ConfigureWebhook("https://hooks.example.com/cpg",material.Ciphertext,1,Now);var second=p.GenerateAndProtect();t.ConfigureWebhook("https://hooks.example.com/cpg",second.Ciphertext,2,Now.AddMinutes(1));Assert.Equal(2,w.SigningSecretVersion);Assert.Equal(second.Ciphertext,w.SigningSecretCiphertext);}finally{Directory.Delete(path,true);}}
    private static Merchant ActiveMerchant(){var m=MerchantTestFactory.Create(Guid.NewGuid(),"فروشگاه",Now);m.Activate(Now);return m;}
}
